svg.script:
(function () {
  const svg = document.documentElement;
  const panel = document.getElementById('focus_panel');
  const panelPreview = document.getElementById('focus_panel_preview');
  let locked = null;

  function clearPreview(preview) {
    if (!preview) return;
    preview.querySelectorAll('.spotlight-hidden').forEach(function (element) {
      element.classList.remove('spotlight-hidden');
    });
    preview.querySelectorAll('[data-spotlight-original-fill-opacity]').forEach(function (element) {
      element.style.fillOpacity = element.getAttribute('data-spotlight-original-fill-opacity');
      element.removeAttribute('data-spotlight-original-fill-opacity');
    });
  }

  function isDefinition(element) {
    return ['defs', 'style', 'title', 'desc'].includes(element.localName);
  }

  function isolateBranch(container, target) {
    Array.from(container.children).forEach(function (child) {
      if (isDefinition(child)) return;
      if (child === target) return;
      if (child.contains(target)) {
        isolateBranch(child, target);
      } else {
        child.classList.add('spotlight-hidden');
      }
    });
  }

  function showPanel(item, sourcePreview) {
    panelPreview.replaceChildren();
    Array.from(sourcePreview.children).forEach(function (child) {
      const copy = child.cloneNode(true);
      panelPreview.appendChild(copy);
    });
    const idMap = new Map();
    panelPreview.querySelectorAll('[id]').forEach(function (element) {
      const original = element.id;
      const replacement = 'focus_copy_' + original;
      idMap.set(original, replacement);
      element.id = replacement;
    });
    panelPreview.querySelectorAll('*').forEach(function (element) {
      Array.from(element.attributes).forEach(function (attribute) {
        let value = attribute.value;
        idMap.forEach(function (replacement, original) {
          value = value.replaceAll('url(#' + original + ')', 'url(#' + replacement + ')');
          if (attribute.name === 'href' || attribute.name === 'xlink:href') {
            if (value === '#' + original) value = '#' + replacement;
          }
        });
        if (value !== attribute.value) element.setAttribute(attribute.name, value);
      });
    });
    document.getElementById('focus_id').textContent = item.textContent;
    setLines(document.getElementById('focus_description'), item.getAttribute('data-description') || '?', 44);
    setLines(document.getElementById('focus_input'), item.getAttribute('data-input') || '?', 44);
    panel.setAttribute('visibility', 'visible');
    positionPanel();
  }

  function setLines(node, value, limit) {
    while (node.firstChild) node.removeChild(node.firstChild);
    const words = value.split(/\s+/);
    const lines = [];
    let line = '';
    words.forEach(function (word) {
      if (line && (line + ' ' + word).length > limit) {
        lines.push(line);
        line = word;
      } else {
        line = line ? line + ' ' + word : word;
      }
    });
    if (line) lines.push(line);
    lines.forEach(function (text, index) {
      if (index) node.appendChild(document.createTextNode(' '));
      const span = document.createElementNS('http://www.w3.org/2000/svg', 'tspan');
      span.setAttribute('x', node.getAttribute('x'));
      span.setAttribute('dy', index ? '15' : '0');
      span.textContent = text;
      node.appendChild(span);
    });
  }

  function positionPanel() {
    if (panel.getAttribute('visibility') !== 'visible') return;
    const bounds = svg.getBoundingClientRect();
    const scale = bounds.width / 1000;
    const panelBounds = panel.getBBox();
    const minX = (12 - bounds.left) / scale - panelBounds.x;
    const maxX = (window.innerWidth - 12 - bounds.left) / scale - panelBounds.x - panelBounds.width;
    const x = Math.max(minX, Math.min(0, maxX));
    const documentTop = bounds.top + window.scrollY;
    const height = svg.viewBox.baseVal.height;
    const desired = (window.scrollY - documentTop + 12) / scale;
    const y = Math.max(12, Math.min(desired, height - 540));
    panel.setAttribute('transform', 'translate(' + x + ' ' + y + ')');
  }

  function show(item) {
    const preview = document.getElementById(item.getAttribute('data-preview-id'));
    const target = document.getElementById(item.getAttribute('data-focus-id'));
    if (!preview || !target || !preview.contains(target)) return;
    svg.querySelectorAll('[data-preview-key]').forEach(function (candidate) {
      clearPreview(candidate);
      if (candidate === preview) {
        isolateBranch(candidate, target);
      } else {
        Array.from(candidate.children).forEach(function (child) {
          if (!isDefinition(child)) child.classList.add('spotlight-hidden');
        });
      }
    });
    if (target.id.endsWith('_dial_status')) {
      target.setAttribute('data-spotlight-original-fill-opacity', target.style.fillOpacity || '');
      target.style.fillOpacity = '0.65';
    }
    showPanel(item, preview);
  }

  function reset() {
    svg.querySelectorAll('[data-preview-key]').forEach(clearPreview);
    panel.setAttribute('visibility', 'hidden');
    panelPreview.replaceChildren();
  }

  svg.addEventListener('pointerover', function (event) {
    const item = event.target.closest('.element-id');
    if (item && !locked) show(item);
  });
  svg.addEventListener('pointerout', function (event) {
    const item = event.target.closest('.element-id');
    if (item && !locked && !item.contains(event.relatedTarget)) reset();
  });
  svg.addEventListener('click', function (event) {
    const item = event.target.closest('.element-id');
    if (!item) return;
    event.preventDefault();
    if (locked === item) {
      locked = null;
      item.classList.remove('spotlight-selected');
      reset();
    } else {
      svg.querySelectorAll('.element-id.spotlight-selected').forEach(function (node) {
        node.classList.remove('spotlight-selected');
      });
      locked = item;
      item.classList.add('spotlight-selected');
      show(item);
    }
  });
  svg.addEventListener('keydown', function (event) {
    const item = event.target.closest('.element-id');
    if (item && (event.key === 'Enter' || event.key === ' ')) {
      event.preventDefault();
      item.dispatchEvent(new MouseEvent('click', { bubbles: true }));
    }
    if (event.key === 'Escape') {
      locked = null;
      svg.querySelectorAll('.element-id.spotlight-selected').forEach(function (node) {
        node.classList.remove('spotlight-selected');
      });
      reset();
    }
  });
  window.addEventListener('scroll', positionPanel, { passive: true });
  window.addEventListener('resize', positionPanel);
}());
